<?php
defined( 'ABSPATH' ) || exit;

/** Read-only management reports calculated exclusively from posted SQLite journals and snapshots. */
final class MDA_Report_Service {
 private static function validateDates(string $from,string $to):void {
  foreach(array($from,$to) as $date){$d=DateTimeImmutable::createFromFormat('!Y-m-d',$date);if(!$d||$d->format('Y-m-d')!==$date)throw new InvalidArgumentException('بازه تاریخ گزارش معتبر نیست.');}
  if($from>$to)throw new InvalidArgumentException('تاریخ شروع گزارش نباید بعد از تاریخ پایان باشد.');
 }
 public static function profit_and_loss(string $from,string $to):array {
  self::validateDates($from,$to);$q=MDA_Database::connection()->prepare("SELECT a.id,a.account_code,a.account_name,a.account_type,a.normal_balance,d.currency_code,SUM(j.debit_minor) debit_minor,SUM(j.credit_minor) credit_minor FROM mda_accounts a JOIN mda_journal_entries j ON j.account_id=a.id JOIN mda_documents d ON d.id=j.document_id WHERE a.account_type IN ('income','expense') AND d.document_status='posted' AND d.document_date BETWEEN :from AND :to GROUP BY a.id,d.currency_code ORDER BY d.currency_code,a.account_type,a.account_code");$q->execute(array(':from'=>$from,':to'=>$to));$rows=$q->fetchAll();$income=array();$expenses=array();$details=array();
  foreach($rows as $row){$currency=(string)$row['currency_code'];$amount=$row['account_type']==='income'?(int)$row['credit_minor']-(int)$row['debit_minor']:(int)$row['debit_minor']-(int)$row['credit_minor'];$entry=array('account_code'=>$row['account_code'],'account_name'=>$row['account_name'],'account_type'=>$row['account_type'],'currency_code'=>$currency,'debit_minor'=>(int)$row['debit_minor'],'credit_minor'=>(int)$row['credit_minor'],'amount_minor'=>$amount);$details[]=$entry;if($row['account_type']==='income')$income[$currency]=self::safeAdd($income[$currency]??0,$amount);else$expenses[$currency]=self::safeAdd($expenses[$currency]??0,$amount);}
  $currencies=array_unique(array_merge(array_keys($income),array_keys($expenses)));$totals=array();foreach($currencies as $currency)$totals[$currency]=array('income_minor'=>$income[$currency]??0,'expense_minor'=>$expenses[$currency]??0,'net_profit_minor'=>self::safeSub($income[$currency]??0,$expenses[$currency]??0));
  return array('from'=>$from,'to'=>$to,'rows'=>$details,'totals'=>$totals);
 }
 public static function order_profitability(string $from,string $to,int $limit=200):array {
  self::validateDates($from,$to);$q=MDA_Database::connection()->prepare("SELECT s.id,s.document_number,s.order_id,s.document_date,s.currency_code,s.source_type,s.product_total_minor,s.shipping_total_minor,s.fee_total_minor,s.tax_total_minor,s.cogs_total_minor,COALESCE(r.returned_product,0) returned_product,COALESCE(r.returned_cogs,0) returned_cogs,COALESCE(r.returned_tax,0) returned_tax FROM mda_sales_documents s LEFT JOIN (SELECT sales_document_id,SUM(product_total_minor) returned_product,SUM(cogs_reversed_minor) returned_cogs,SUM(tax_total_minor) returned_tax FROM mda_sales_returns GROUP BY sales_document_id) r ON r.sales_document_id=s.id WHERE s.document_date BETWEEN :from AND :to ORDER BY s.id DESC LIMIT :limit");$q->bindValue(':from',$from);$q->bindValue(':to',$to);$q->bindValue(':limit',max(1,min(500,$limit)),PDO::PARAM_INT);$q->execute();$rows=$q->fetchAll();
  foreach($rows as &$row){$row['net_product_minor']=self::safeSub((int)$row['product_total_minor'],(int)$row['returned_product']);$row['net_cogs_minor']=self::safeSub((int)$row['cogs_total_minor'],(int)$row['returned_cogs']);$row['gross_profit_minor']=self::safeSub($row['net_product_minor'],$row['net_cogs_minor']);$row['net_revenue_ex_tax_minor']=self::safeAdd(self::safeAdd($row['net_product_minor'],(int)$row['shipping_total_minor']),(int)$row['fee_total_minor']);}unset($row);return$rows;
 }
 public static function product_profitability(string $from,string $to,int $limit=200):array {
  self::validateDates($from,$to);$q=MDA_Database::connection()->prepare("SELECT l.product_id,l.variation_id,l.product_name_snapshot,l.sku_snapshot,l.quantity_scale,l.currency_code,SUM(l.quantity_scaled) sold_quantity_scaled,COALESCE(SUM(r.returned_quantity_scaled),0) returned_quantity_scaled,SUM(l.revenue_minor) gross_revenue_minor,COALESCE(SUM(r.returned_revenue),0) returned_revenue_minor,SUM(l.cogs_minor) gross_cogs_minor,COALESCE(SUM(r.returned_cogs),0) returned_cogs_minor FROM mda_sales_lines l JOIN mda_sales_documents s ON s.id=l.sales_document_id LEFT JOIN (SELECT sales_line_id,SUM(quantity_scaled) returned_quantity_scaled,SUM(revenue_minor) returned_revenue,SUM(cogs_minor) returned_cogs FROM mda_sales_return_lines GROUP BY sales_line_id) r ON r.sales_line_id=l.id WHERE s.document_date BETWEEN :from AND :to GROUP BY l.product_id,l.variation_id,l.product_name_snapshot,l.sku_snapshot,l.quantity_scale,l.currency_code ORDER BY gross_revenue_minor DESC LIMIT :limit");$q->bindValue(':from',$from);$q->bindValue(':to',$to);$q->bindValue(':limit',max(1,min(500,$limit)),PDO::PARAM_INT);$q->execute();$rows=$q->fetchAll();
  foreach($rows as &$row){$row['net_quantity_scaled']=self::safeSub((int)$row['sold_quantity_scaled'],(int)$row['returned_quantity_scaled']);$row['net_revenue_minor']=self::safeSub((int)$row['gross_revenue_minor'],(int)$row['returned_revenue_minor']);$row['net_cogs_minor']=self::safeSub((int)$row['gross_cogs_minor'],(int)$row['returned_cogs_minor']);$row['gross_profit_minor']=self::safeSub($row['net_revenue_minor'],$row['net_cogs_minor']);}unset($row);return$rows;
 }
 public static function channel_profitability(string $from,string $to):array {
  self::validateDates($from,$to);$q=MDA_Database::connection()->prepare("SELECT s.source_type,s.currency_code,COUNT(*) order_count,SUM(s.product_total_minor) gross_product_minor,SUM(COALESCE(r.returned_product,0)) returned_product_minor,SUM(s.shipping_total_minor) shipping_minor,SUM(s.fee_total_minor) fees_minor,SUM(s.cogs_total_minor) gross_cogs_minor,SUM(COALESCE(r.returned_cogs,0)) returned_cogs_minor FROM mda_sales_documents s LEFT JOIN (SELECT sales_document_id,SUM(product_total_minor) returned_product,SUM(cogs_reversed_minor) returned_cogs FROM mda_sales_returns GROUP BY sales_document_id) r ON r.sales_document_id=s.id WHERE s.document_date BETWEEN :from AND :to GROUP BY s.source_type,s.currency_code ORDER BY s.currency_code,s.source_type");$q->execute(array(':from'=>$from,':to'=>$to));$rows=$q->fetchAll();
  foreach($rows as &$row){$row['net_product_minor']=self::safeSub((int)$row['gross_product_minor'],(int)$row['returned_product_minor']);$row['net_cogs_minor']=self::safeSub((int)$row['gross_cogs_minor'],(int)$row['returned_cogs_minor']);$row['gross_profit_minor']=self::safeSub($row['net_product_minor'],$row['net_cogs_minor']);$row['net_revenue_ex_tax_minor']=self::safeAdd(self::safeAdd($row['net_product_minor'],(int)$row['shipping_minor']),(int)$row['fees_minor']);}unset($row);return$rows;
 }
 public static function inventory_valuation(int $warehouseId=0):array {
  $sql='SELECT c.product_id,c.variation_id,c.warehouse_id,c.quantity_scaled,c.quantity_scale,c.average_cost_minor,c.currency_code,w.warehouse_name FROM mda_product_cost_state c JOIN mda_warehouses w ON w.id=c.warehouse_id';$params=array();if($warehouseId>0){$sql.=' WHERE c.warehouse_id=:warehouse';$params[':warehouse']=$warehouseId;}$sql.=' ORDER BY w.warehouse_name,c.product_id,c.variation_id';
  $q=MDA_Database::connection()->prepare($sql);$q->execute($params);$rows=$q->fetchAll();$totals=array();
  foreach($rows as &$row){$qty=(int)$row['quantity_scaled'];$scale=(int)$row['quantity_scale'];$unit=(int)$row['average_cost_minor'];if($qty<0||$scale<1||$unit<0)throw new RuntimeException('وضعیت موجودی/بهای تمام‌شده نامعتبر است؛ گزارش ارزش موجودی متوقف شد.');$value=self::mulDivRound($qty,$unit,$scale);$row['inventory_value_minor']=$value;$currency=(string)$row['currency_code'];$totals[$currency]=self::safeAdd($totals[$currency]??0,$value);}unset($row);
  return array('rows'=>$rows,'totals'=>$totals,'warehouse_id'=>$warehouseId);
 }
 private static function safeAdd(int $a,int $b):int {if($b>0&&$a>PHP_INT_MAX-$b)throw new OverflowException('جمع گزارش بیش از ظرفیت عدد صحیح است.');if($b<0&&$a<PHP_INT_MIN-$b)throw new OverflowException('جمع گزارش بیش از ظرفیت عدد صحیح است.');return$a+$b;}
 private static function safeSub(int $a,int $b):int {if($b>0&&$a<PHP_INT_MIN+$b)throw new OverflowException('تفریق گزارش بیش از ظرفیت عدد صحیح است.');if($b<0&&$a>PHP_INT_MAX+$b)throw new OverflowException('تفریق گزارش بیش از ظرفیت عدد صحیح است.');return$a-$b;}
 private static function mulDivRound(int $a,int $b,int $d):int {if($a<0||$b<0||$d<1||($a>0&&$b>intdiv(PHP_INT_MAX,$a)))throw new OverflowException('محاسبه ارزش موجودی بیش از ظرفیت عدد صحیح است.');$v=$a*$b;$q=intdiv($v,$d);$r=$v%$d;if($r>=intdiv($d,2)+($d%2))$q++;return$q;}
}
